### Step 3 · Chat Interface Component with Streaming Reader

Create `frontend/components/ChatInterface.tsx`:

```tsx
'use client';

import React, { useState, useRef, useEffect } from 'react';
import { useDocument } from '@/context/DocumentContext';
import { Send, Sparkles, BookOpen } from 'lucide-react';

interface Message {
  role: 'user' | 'assistant';
  content: string;
  sources?: Array<{ page_number: number; chunk_index: number; snippet: string }>;
}

export function ChatInterface() {
  const { documentId, setCurrentPage, setActiveHighlight } = useDocument();
  const [messages, setMessages] = useState<Message[]>([]);
  const [input, setInput] = useState('');
  const [isStreaming, setIsStreaming] = useState(false);
  const chatEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const handleSend = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!input.trim() || !documentId || isStreaming) return;

    const userMsg = input;
    setInput('');
    setMessages((prev) => [...prev, { role: 'user', content: userMsg }]);
    setIsStreaming(true);

    const response = await fetch('http://localhost:8000/query/stream', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ document_id: documentId, question: userMsg }),
    });

    if (!response.body) return;

    const reader = response.body.getReader();
    const decoder = new TextDecoder();
    let assistantContent = '';
    let sources: any[] = [];

    setMessages((prev) => [...prev, { role: 'assistant', content: '', sources: [] }]);

    while (true) {
      const { done, value } = await reader.read();
      if (done) break;

      const chunkText = decoder.decode(value);
      const lines = chunkText.split('\n');

      for (const line of lines) {
        if (line.startsWith('data: ')) {
          try {
            const parsed = JSON.parse(line.slice(6));
            if (parsed.type === 'sources') {
              sources = parsed.data;
            } else if (parsed.type === 'token') {
              assistantContent += parsed.content;
              setMessages((prev) => {
                const updated = [...prev];
                updated[updated.length - 1] = {
                  role: 'assistant',
                  content: assistantContent,
                  sources,
                };
                return updated;
              });
            }
          } catch (err) {
            // partial JSON line, continue reading buffer
          }
        }
      }
    }
    setIsStreaming(false);
  };

  return (
    <div className="flex flex-col h-full bg-stone-900 border-l border-stone-800 text-stone-100">
      <div className="p-4 border-b border-stone-800 flex items-center gap-2">
        <Sparkles className="w-5 h-5 text-indigo-400" />
        <h2 className="font-medium text-sm">Research Assistant</h2>
      </div>

      <div className="flex-1 overflow-y-auto p-4 space-y-4">
        {messages.map((m, idx) => (
          <div key={idx} className={`flex flex-col ${m.role === 'user' ? 'items-end' : 'items-start'}`}>
            <div className={`max-w-[85%] rounded-lg p-3 text-sm leading-relaxed ${
              m.role === 'user' ? 'bg-indigo-600 text-white' : 'bg-stone-800 text-stone-200 border border-stone-700'
            }`}>
              {m.content}
            </div>
            {m.sources && m.sources.length > 0 && (
              <div className="flex flex-wrap gap-1.5 mt-2">
                {m.sources.map((s, sIdx) => (
                  <button
                    key={sIdx}
                    onClick={() => {
                      setCurrentPage(s.page_number);
                      setActiveHighlight(s.snippet);
                    }}
                    className="flex items-center gap-1 text-xs px-2 py-0.5 rounded bg-stone-800 border border-stone-700 text-stone-400 hover:text-indigo-300 hover:border-indigo-500 transition-colors"
                  >
                    <BookOpen className="w-3 h-3" />
                    Page {s.page_number}
                  </button>
                ))}
              </div>
            )}
          </div>
        ))}
        <div ref={chatEndRef} />
      </div>

      <form onSubmit={handleSend} className="p-4 border-t border-stone-800 flex gap-2">
        <input
          type="text"
          value={input}
          onChange={(e) => setInput(e.target.value)}
          placeholder="Ask anything about this document..."
          disabled={isStreaming || !documentId}
          className="flex-1 bg-stone-950 border border-stone-800 rounded px-3 py-2 text-sm focus:outline-none focus:border-indigo-500 disabled:opacity-50"
        />
        <button
          type="submit"
          disabled={isStreaming || !documentId}
          className="p-2 bg-indigo-600 hover:bg-indigo-500 rounded text-white disabled:opacity-50 transition-colors"
        >
          <Send className="w-4 h-4" />
        </button>
      </form>
    </div>
  );
}
```

