```typescript
import { applyPatch } from 'diff';

export function computeModifiedCode(originalCode: string, unifiedDiff: string): string {
  // If diff is a patch representation, use jsdiff to apply it
  try {
    const patched = applyPatch(originalCode, unifiedDiff);
    if (patched !== false) return patched;
  } catch (err) {
    console.warn('Failed to parse clean patch, falling back to manual extract', err);
  }

  // Basic fallback: extract '+' lines
  const lines = unifiedDiff.split('\n');
  const added = lines.filter((l) => l.startsWith('+') && !l.startsWith('+++')).map((l) => l.slice(1));
  return added.length ? added.join('\n') : originalCode;
}
```

