import { prisma } from '../config/prisma';
import { redisClient } from '../config/redis';
import { Base62Service } from './base62.service';

export class UrlService {
  public static async createShortUrl(originalUrl: string, customAlias?: string): Promise<{ shortCode: string; originalUrl: string }> {
    if (customAlias) {
      // Validate custom alias format
      if (!/^[a-zA-Z0-9_-]{3,20}$/.test(customAlias)) {
        throw new Error('Custom alias must be 3-20 alphanumeric characters');
      }
      const existing = await prisma.url.findUnique({ where: { shortCode: customAlias } });
      if (existing) {
        throw new Error('Custom alias is already in use');
      }

      const url = await prisma.url.create({
        data: { shortCode: customAlias, originalUrl }
      });
      return { shortCode: url.shortCode, originalUrl: url.originalUrl };
    }

    // Generate atomic sequence ID starting at offset to guarantee 6+ characters
    const sequenceId = await redisClient.incr('sequence:url_id');
    const offsetId = BigInt(sequenceId) + 100_000_000n; // Guarantees min 6 chars
    const shortCode = Base62Service.encode(offsetId);

    const url = await prisma.url.create({
      data: { shortCode, originalUrl }
    });

    return { shortCode: url.shortCode, originalUrl: url.originalUrl };
  }
}
```

