### Step 2 · Consumer Worker: Batch Processor

Create `backend/src/workers/clickConsumer.ts`:

```typescript
import { createClient } from 'redis';
import { prisma } from '../config/prisma';
import dotenv from 'dotenv';
dotenv.config();

const STREAM_KEY = 'stream:clicks';
const GROUP_NAME = 'analytics_workers';
const CONSUMER_NAME = 'worker_1';

async function startWorker() {
  const redis = createClient({ url: process.env.REDIS_URL });
  await redis.connect();
  console.log('👷 Analytics Clickstream Worker started');

  // Create Consumer Group if it doesn't exist
  try {
    await redis.xGroupCreate(STREAM_KEY, GROUP_NAME, '0', { MKSTREAM: true });
  } catch (err: any) {
    if (!err.message.includes('BUSYGROUP')) throw err;
  }

  while (true) {
    try {
      // Read batch of up to 100 items, blocking for 2000ms if empty
      const response = await redis.xReadGroup(
        GROUP_NAME,
        CONSUMER_NAME,
        [{ key: STREAM_KEY, id: '>' }],
        { COUNT: 100, BLOCK: 2000 }
      );

      if (!response || response.length === 0) continue;

      const entries = response[0].messages;
      const clicksToInsert = [];
      const messageIds: string[] = [];

      for (const entry of entries) {
        messageIds.push(entry.id);
        const data = entry.message;

        // Lookup url record
        const url = await prisma.url.findUnique({
          where: { shortCode: data.shortCode },
          select: { id: true }
        });

        if (url) {
          clicksToInsert.push({
            urlId: url.id,
            referrer: data.referrer,
            country: 'US', // Enriched in Phase 6
            browser: 'Chrome', // Enriched in Phase 6
            device: 'Desktop', // Enriched in Phase 6
            createdAt: new Date(Number(data.timestamp))
          });
        }
      }

      // Batch write to database
      if (clicksToInsert.length > 0) {
        await prisma.clickEvent.createMany({ data: clicksToInsert });
      }

      // Acknowledge processed messages
      await redis.xAck(STREAM_KEY, GROUP_NAME, messageIds);
    } catch (err) {
      console.error('Error processing stream batch:', err);
      await new Promise(r => setTimeout(r, 1000));
    }
  }
}

startWorker();
```

