### Step 2 · Enrichment Utility Module

Create `backend/src/services/enrichment.service.ts`:

```typescript
import { UAParser } from 'ua-parser-js';
import geoip from 'geoip-lite';

export interface EnrichedMetadata {
  country: string;
  browser: string;
  device: string;
  isBot: boolean;
}

export class EnrichmentService {
  public static enrich(ip: string, userAgent: string): EnrichedMetadata {
    // 1. User-Agent parsing
    const parser = new UAParser(userAgent);
    const browser = parser.getBrowser().name || 'Other';
    const deviceType = parser.getDevice().type || 'Desktop';

    // 2. Bot detection
    const isBot = /bot|googlebot|crawler|spider|robot|crawling/i.test(userAgent);

    // 3. GeoIP lookup
    const cleanIp = ip.replace('::ffff:', '');
    const geo = geoip.lookup(cleanIp);
    const country = geo ? geo.country : 'UNKNOWN';

    return {
      country,
      browser,
      device: deviceType === 'mobile' ? 'Mobile' : deviceType === 'tablet' ? 'Tablet' : 'Desktop',
      isBot
    };
  }
}
```

